export const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
export const ease=t=>{t=clamp(t);return t*t*(3-2*t);};
export const mix=(a,b,t)=>a+(b-a)*t;
export function pathMetric(points){const cumulative=[0];for(let i=1;i<points.length;i++)cumulative.push(cumulative.at(-1)+Math.hypot(points[i][0]-points[i-1][0],points[i][2]-points[i-1][2]));return{points,cumulative,total:cumulative.at(-1)};}
export function samplePath(metric,t){const d=clamp(t)*metric.total,c=metric.cumulative;let lo=0,hi=c.length-1;while(lo<hi){const mid=(lo+hi)>>1;if(c[mid]<d)lo=mid+1;else hi=mid;}const i=Math.max(1,lo),f=(d-c[i-1])/(c[i]-c[i-1]||1);return {point:metric.points[i-1].map((v,k)=>mix(v,metric.points[i][k],f)),index:i,f};}
export function nearestPosition(route,metric,anchor){if(typeof anchor==='number')return{t:clamp(anchor),errorKm:0};let best=Infinity,along=0;const cos=Math.cos(anchor[1]*Math.PI/180);for(let i=1;i<route.coordinates.length;i++){const a=route.coordinates[i-1],b=route.coordinates[i],dx=(b[0]-a[0])*cos,dy=b[1]-a[1],px=(anchor[0]-a[0])*cos,py=anchor[1]-a[1],f=clamp((px*dx+py*dy)/(dx*dx+dy*dy||1)),d=Math.hypot(px-dx*f,py-dy*f);if(d<best){best=d;along=mix(metric.cumulative[i-1],metric.cumulative[i],f);}}return{t:along/metric.total,errorKm:best*111};}
export function buildSchedule(stops,overview=false){let clock=0;const chapters=stops.map((stop,i)=>{const travel=overview?(i?4.8:0):i?clamp(6+Math.sqrt(Math.max(0,stop.t-stops[i-1].t))*18,6,16):0;const arrival=clock+travel;const hold=stop.hold??(stop.final?12:stop.kind==='CONFLUENCE'?10:8.5);const s={...stop,index:i,start:clock,arrival,end:arrival+hold,hold,travel};clock=s.end;return s;});return{chapters,duration:clock};}
export function stateAt(schedule,time){const seconds=clamp(time,0,schedule.duration);const c=schedule.chapters.find(x=>seconds<x.end)||schedule.chapters.at(-1),previous=schedule.chapters[Math.max(0,c.index-1)];const travelling=seconds<c.arrival;const phase=travelling?ease((seconds-c.start)/(c.travel||1)):clamp((seconds-c.arrival)/c.hold);const t=travelling?mix(previous.t??0,c.t??0,phase):c.t??0;return{chapter:c,previous,travelling,phase,t,seconds,done:seconds>=schedule.duration};}
export function headingAt(metric,t){const a=samplePath(metric,t-.012).point,b=samplePath(metric,t+.018).point;return Math.atan2(b[0]-a[0],b[2]-a[2]);}
export function shortestAngle(a,b,t){const d=((b-a+Math.PI*3)%(Math.PI*2))-Math.PI;return a+d*t;}
